const roomSelection:{simulation:string;project:string}={simulation:'',project:''};
const simulationErrorLabels:Record<string,string>={SIMULATION_PRICING_REQUIRED:'自动多轮讨论需要已核对的价格。请在房间设置的高级预算中填写模型价格与费用上限。',SIMULATION_ACCOUNTING_UNKNOWN:'先前请求的用量或费用仍有未知项，自动讨论已停止。可以核对记录后手动发送单次消息。',SIMULATION_USAGE_UNKNOWN:'模型返回的用量信息不完整，自动讨论已暂停，费用仍需核对。',SIMULATION_CONTEXT_TOO_LARGE:'当前上下文超出安全范围。消息草稿已保留，请缩短输入或调整角色资料后再试。',SIMULATION_WORKSPACE_DIRTY:'源工作区有未提交修改。请先在工作区页面审阅并保存这些修改，再准备隔离任务。',SIMULATION_MEMORY_UNAVAILABLE:'当前环境尚未提供仿真记忆服务。',SIMULATION_CANCELLED:'生成已停止。已发生的调用费用可能尚未确认。'};
const messageOf=(error:unknown)=>{const code=error&&typeof error==='object'&&'code'in error?String(error.code):error instanceof Error?error.message:'';return simulationErrorLabels[code]??(error instanceof Error?error.message:'操作未完成，请重试。');};
const statusLabel=(status:string)=>({idle:'等待发言',running:'正在讨论',paused:'已暂停',completed:'讨论已结束',failed:'需要处理',queued:'待启动',verified:'已验证','awaiting-review':'待验收',cancelled:'已取消'}[status]??status);
const taskStatusLabel=(status:string)=>({queued:'待启动',pending:'待启动',running:'执行中',waiting:'等待处理',completed:'已完成',paused:'已暂停',failed:'执行失败',cancelled:'已取消',unknown:'状态未知'}[status]??status);
const sceneLabel=(scene:string)=>({free:'自由聊天',brainstorm:'头脑风暴',product:'产品需求',project:'项目开发团队',review:'代码审查与诊断'}[scene]??scene);
const timeLabel=(at:string|number)=>new Date(at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});
