const emptyRole=():PersonaRole=>({id:'',rev:0,name:'',avatar:'',description:'',sourceText:'',examples:[],behavior:{silenceAllowed:true,willingness:.6,interests:[],cooldownMs:1000,maxConsecutiveTurns:2},model:null,memoryScopes:[],allowedTools:[],versions:[]});
